import { useEffect, useState } from 'preact/hooks';
import { api } from '../../api.js';
import { Link, Field, ErrorNotice, Loading, StatusBadge, useResource } from '../../components/ui.jsx';
import { CursorNavigation, useCursorPage } from '../../components/paginated.jsx';
import { dependencyState, focusDependency, backDependency, expandDependency } from './dependency-state.js';
function NeighborPage({ issueId, projectId, filters, onFocus, expanded = [], onExpand, parentId }) {
  const page = useCursorPage('/issues/' + issueId + '/dependencies', filters, 0, { projectId, entityTypes: ['relation', 'issue', 'workflow'] });
  const denied = [401, 403, 404].includes(page.error?.status);
  return <div aria-label={'Dependencies of ' + issueId}>
    {!page.loading && !page.error && !page.items.length && <p>No matching dependencies.</p>}
    {!denied && <ul>{page.items.map(relation => {
      const other = relation.otherIssue;
      return <li key={relation.id} data-dependency-id={other.id}>
        <span>{relation.label} </span><Link href={'/issues/' + other.id}>{other.key} · {other.title}</Link> {' '}
        <StatusBadge tone={other.statusCategory}>{other.statusName} · {other.statusCategory === 'done' ? 'Done' : 'Unfinished'}</StatusBadge>
        <div class="actions">
          <button type="button" onClick={() => onFocus(other.id)}>Focus {other.key}</button>
          {onExpand && <button type="button" aria-expanded={expanded.includes(relation.id)} onClick={() => onExpand(relation.id)}>
            {expanded.includes(relation.id) ? 'Collapse' : 'Expand'} dependencies of {other.key}
          </button>}
        </div>
        {onExpand && expanded.includes(relation.id) && <section aria-label={'Expanded ' + other.key}>
          <h4>{other.key} · {other.title}</h4>
          <NeighborPage key={other.id + JSON.stringify(filters)} issueId={other.id} projectId={projectId} filters={filters} onFocus={onFocus} parentId={issueId} />
        </section>}
        {parentId === other.id && <small>This link returns to the issue you expanded from.</small>}
      </li>;
    })}</ul>}
    <CursorNavigation page={page} label="dependencies" />
    <button type="button" disabled={page.loading} onClick={() => void page.refresh()}>Refresh dependencies</button>
  </div>;
}
export function DependencyExplorer({ issue }) {
  const [state, setState] = useState(() => dependencyState(issue.id));
  const [filters, setFilters] = useState({ kind: 'all', direction: 'all' });
  useEffect(() => { setState(dependencyState(issue.id)); setFilters({ kind: 'all', direction: 'all' }); }, [issue.id, issue.projectId]);
  const focus = useResource(() => api.get('/issues/' + state.focusId), [state.focusId]);
  const safeScope = state.rootId === issue.id;
  const current = safeScope ? focus.data?.issue : null;
  function filter(field, value) { setFilters(previous => ({ ...previous, [field]: value })); setState(previous => ({ ...previous, expanded: [] })); }
  return <section class="panel" aria-label="Dependency explorer">
    <h2>Dependency explorer</h2>
    <p>Follow blockers, duplicate chains and related work within {issue.key.split('-').slice(0, -1).join('-')}. Expand a neighbor to inspect its links or make it the current focus.</p>
    <div class="actions">
      <button type="button" disabled={!state.history.length} onClick={() => setState(backDependency)}>Back to previous focus</button>
      <button type="button" disabled={state.focusId === issue.id} onClick={() => setState(dependencyState(issue.id))}>Return to {issue.key}</button>
      <span>Focus history: {state.history.length} step{state.history.length === 1 ? '' : 's'}</span>
    </div>
    <div class="actions">
      <Field label="Dependency kind"><select name="dependencyKind" value={filters.kind} onChange={event => filter('kind', event.currentTarget.value)}>
        <option value="all">All relations</option><option value="blocks">Blockers</option><option value="duplicates">Duplicates</option><option value="relates">Related work</option>
      </select></Field>
      <Field label="Dependency direction"><select name="dependencyDirection" value={filters.direction} onChange={event => filter('direction', event.currentTarget.value)}>
        <option value="all">Both directions</option><option value="outgoing">Outgoing</option><option value="incoming">Incoming</option>
      </select></Field>
    </div>
    <ErrorNotice error={focus.error} />
    {focus.error && <button type="button" onClick={focus.refresh}>Reload dependency focus</button>}
    {focus.loading && <Loading label="Loading dependency focus…" />}
    {current && <div>
      <h3 data-testid="dependency-focus">{current.key} · {current.title}</h3>
      <StatusBadge tone={current.statusCategory}>{current.statusName} · {current.statusCategory === 'done' ? 'Done' : 'Unfinished'}</StatusBadge>
      <NeighborPage key={current.id} issueId={current.id} projectId={issue.projectId} filters={filters} expanded={state.expanded}
        onExpand={id => setState(previous => expandDependency(previous, id))} onFocus={id => setState(previous => focusDependency(previous, id))} />
    </div>}
  </section>;
}
export function CycleExplanation({ cycle }) {
  if (!cycle?.path?.length) return null;
  return <aside class="notice" aria-label="Dependency cycle explanation">
    <h3>This link would close a {cycle.kind === 'blocks' ? 'blocker' : 'duplicate'} cycle</h3>
    <p>The selected target already reaches this issue along these existing links. Remove or change the appropriate relation before adding the new link.</p>
    <ol>{cycle.path.map((issue, index) => <li key={issue.id}>
      <Link href={'/issues/' + issue.id}>{issue.key} · {issue.title}</Link>
      {index < cycle.path.length - 1 && <span> {cycle.kind === 'blocks' ? 'blocks' : 'duplicates'} the next issue</span>}
    </li>)}</ol>
  </aside>;
}
"))]), Map([("op", Text("write")), ("path", Text("/docs/work-issues.md")), ("content", Text("# Issues, labels and discussion

Crew issues belong to one project and keep a sequential `<PROJECT>-<number>` key. The server allocates the number and inserts the issue in one transaction; rejected creation does not consume a number. A project key cannot change after it has an issue. Work in archived projects remains readable; restore the project before changing issues, labels, comments or relations.

## Issue fields and editing

Create an issue from the project issue list, or use **New issue** after choosing a project in the Issues page. Title is required and limited to 500 characters. Description preserves Markdown up to 100,000 characters. The editor includes workflow status, priority, organization-member assignee, numeric estimate, calendar due date, parent issue and labels. Priority values are 0 no priority, 1 urgent, 2 high, 3 normal and 4 low. Estimates accept nonnegative finite numbers up to 1,000,000, including fractions and zero. Dates use a real `YYYY-MM-DD` UTC calendar date. Empty optional fields clear their values.

Status, parent and labels must belong to the issue's project. A parent cannot be the issue itself or its descendant. Assignees must currently belong to the organization. Removed organization members cannot be newly assigned. Parent selection searches title/key and has paginated results; the id field also accepts an existing opaque issue id. The assignee chooser and label choices load additional pages explicitly.

Issue lists support literal title/key search, status, priority, assignee, label and parent filters. `assigneeId=none` and `parentId=none` select unset fields. List order is ascending project number, with an opaque cursor and a limit from 1 to 200 (default 50). The web uses 25 rows and previous/next navigation. Editing an issue changes only the supplied API fields. Issue keys, numbers, project ownership and creator are server-owned. There is no destructive issue deletion endpoint; use workflow state and project archival to retain discussion and planning history.

Sprint membership is changed exclusively through sprint scope APIs and the sprint UI/CLI. `sprintId` in issue POST/PATCH is an unknown field and returns 422; this keeps sprint validation and scope snapshots in the planning service. The issue presenter includes its current sprint id and board rank.

## Safe Markdown and mentions

Descriptions and comments render a small deterministic Markdown subset: headings, paragraphs/line breaks, unordered/ordered lists, block quotes, bold, italic, inline code, fenced code, and links. Raw HTML is escaped. Links allow absolute HTTP, HTTPS and mailto URLs; executable/data/relative URLs remain escaped text. Images and embedded HTML are not supported. Both client previews and server HTML use the same shared renderer.

Comments support `@user-id`, `@email@example.com`, and a single-word `@name`. Mentions resolve only current members of the issue's organization; repeated mentions resolve once. Code spans, fenced code and link text do not notify. A multiword name is best addressed by email or opaque user id. Comments preserve their original text and expose resolved `mentionIds` for notifications. Description snapshots also preserve their source for search consumers.

Add, edit or remove comments in the issue detail discussion. The comment author and organization owners/admins may edit or remove a comment; other members cannot change it. Guests with explicit project access may read and comment. Guests cannot modify issues, labels or relations. Editing a comment replaces its resolved mention set. Comment lists paginate by creation timestamp and id.

## Relations and labels

`blocks` is directional: source blocks target; target displays **blocked by**. `duplicates` is directional: source duplicates the selected canonical target; target displays **duplicated by**. An issue has at most one outgoing duplicate target. Directed blocker and duplicate cycles, including transitive cycles, are rejected. `relates` is symmetric: both issues display **relates to**, and reverse creation is rejected as a duplicate. All relations remain within one project and cannot target the same issue. Remove a relation before selecting a different duplicate target.

Project label settings create, rename, recolor and delete labels. Names are 1–80 characters and unique ignoring case within a project. Colors are six-digit hex values such as `#2563eb`. Deleting a label clears its issue assignments. Renaming, recoloring or deleting a label emits updated full issue snapshots for linked issues. Issue label replacement validates the complete set before writing it.

## HTTP API

All paths below are under `/api/v1`, require authentication, and return the common JSON error envelope. Invalid fields return 422 with field details. A list is `{items,nextCursor}`; cursors are opaque. Create returns 201; deletion returns 204.

| Method and path | Body / response | Permission |
| --- | --- | --- |
| GET `/projects/:projectId/issues` | Filters `q,statusId,priority,assigneeId,parentId,labelId,key,limit,cursor`; `{items:Issue[],nextCursor}` | issue:read |
| POST `/projects/:projectId/issues` | `{title,description?,statusId?,priority?,assigneeId?,estimate?,dueDate?,parentId?,labelIds?}` → `{issue}` | issue:write |
| GET `/issues/:issueId` | `{issue}` including `descriptionHtml` | issue:read |
| PATCH `/issues/:issueId` | Nonempty subset of editable fields → `{issue}` | issue:write |
| GET `/projects/:projectId/labels` | `{items:Label[],nextCursor}` | issue:read |
| POST `/projects/:projectId/labels` | `{name,color?}` → `{label}` | issue:write |
| PATCH `/projects/:projectId/labels/:labelId` | `{name?,color?}` → `{label}` | issue:write |
| DELETE `/projects/:projectId/labels/:labelId` | Removes label and assignments | issue:write |
| GET `/issues/:issueId/comments` | `{items:Comment[],nextCursor}` | issue:read |
| POST `/issues/:issueId/comments` | `{body}` → `{comment}` | comment:write |
| PATCH `/comments/:commentId` | `{body}` → `{comment}`; author/admin rule | comment:write |
| DELETE `/comments/:commentId` | author/admin rule | comment:write |
| GET `/issues/:issueId/relations` | `{items:Relation[],nextCursor}` | issue:read |
| POST `/issues/:issueId/relations` | `{kind,targetId}` → `{relation}` | issue:write |
| DELETE `/relations/:relationId` | Removes directional or symmetric relation | issue:write |

Permissions always include both the actual organization and project context. Opaque ids identify resources. A key can be used as a project list filter, but path parameters and CLI mutation commands use ids. Every mutation emits its actor, organization, project, entity, action, before/after public values and UTC time through the shared event bus. Issue snapshots include all fields and labels; comment snapshots include issue id, body, rendered HTML and mention ids; relation snapshots preserve source, target, kind and the other issue.

## CLI

Configure `crew login` or a personal token as described in the root README. Add `--json` for complete machine-readable results, including pagination cursors. The CLI uses the same API and permissions as the web.

```sh
crew issue create --project PROJECT_ID --title 'Ship editor' --description '**Context**' --priority 2 --assignee USER_ID --estimate 3.5 --due 2027-01-31 --parent PARENT_ID --labels LABEL_ID
crew issue list --project PROJECT_ID --q editor --status STATUS_ID --limit 25
crew issue list --project PROJECT_ID --cursor OPAQUE_CURSOR --json
crew issue show ISSUE_ID --json
crew issue update ISSUE_ID --status STATUS_ID --assignee none --estimate none --due none --parent none --labels none
crew issue update ISSUE_ID --description-file ./context.md
crew issue labels create --project PROJECT_ID --name Feature --color '#2563eb'
crew issue labels list --project PROJECT_ID
crew issue labels update LABEL_ID --project PROJECT_ID --name Delivery
crew issue labels delete LABEL_ID --project PROJECT_ID
crew issue comment add ISSUE_ID --body '**Review** @person@example.com'
crew issue comment update COMMENT_ID --body-file ./comment.md
crew issue comment list ISSUE_ID --limit 20
crew issue comment delete COMMENT_ID
crew issue relations add ISSUE_ID --target OTHER_ISSUE_ID --kind blocks
crew issue relations list ISSUE_ID
crew issue relations remove RELATION_ID
crew issue help
```

`--description`/`--description-file` and `--body`/`--body-file` are mutually exclusive. Numeric, date, priority, label and required-id errors fail before an HTTP mutation when possible; server membership, permission and project checks remain authoritative. `none` clears nullable fields; `--labels none` replaces the label set with an empty array. List output preserves a `nextCursor` in JSON; use it with the same filters.

## Verification

Focused tests cover 22 issue HTTP cases, 12 shared schema/Markdown cases, seven issue web-state cases, seven issue CLI cases against a real server, and one real Chromium flow. The browser flow creates an issue with every field, previews escaped Markdown, edits its title, creates/edits a mentioned comment, adds a blocker and creates/edits a label, then verifies persisted values through HTTP. Acceptance hooks additionally retain issue/label/comment/relation state across server restart and audit every issue route's anonymous denial. Later people/insight integration supplies scoped token authentication and notification/search persistence acceptance.

Issue snapshots also expose `mentionIds` resolved from description through the same canonical current-member resolver used by comments. Blank-only comments return 422.

## Named issue context and authoring

The global Issues page pages through all current organizations and projects. The assignee filter offers Any assignee, Unassigned and Assigned to me, followed by named current organization members on explicit pages. Selection and filters are retained in the URL; changing organization or project clears incompatible context and filters. Reopening a deep link resolves the selected current teammate by exact id, without loading earlier member pages. Removed membership displays an unavailable-member selection instead of guessing a name. Transient read errors retain the visible page and expose Reload; current access denials clear protected server data.

Descriptions and comment create/edit share one Markdown composer and the existing safe renderer. Bold, italic, inline/multiline code, bullet/numbered lists and link actions apply at the current caret or selection. Links start with a safe editable HTTPS destination. The concise guide lists supported syntax. Mention teammate opens a paginated named chooser; use arrows and Enter, click a name, or Escape to dismiss it. The composer inserts a stable current member mention at the saved selection. Mentions inside code, link syntax and raw HTML do not notify. A mention in another prose location cannot make an insertion inside excluded syntax valid. Server current-membership and notification access checks remain authoritative.

Typed text, selection and deliberate preview mode survive background refresh and transient errors. Comment compose and each edited comment keep separate recoverable drafts while switching contexts. Explicit Cancel discards that edit; an acknowledged save clears only the saved draft. A concurrent comment removal preserves edit text and explains that it cannot be saved back to the removed comment.

## Concurrent editing and conditional writes

Issue and comment API presentations include an opaque `revision`. It describes canonical content, rather than a timestamp. Issue revisions include every editable field, a sorted unique label-id set, board rank and current sprint; comment revisions include body and stable resource context. Display names and timestamps do not change revision. Clients must treat revisions as opaque.

`PATCH /issues/:issueId`, `PATCH /comments/:commentId` and `DELETE /comments/:commentId` accept optional `If-Match: REVISION` (a quoted revision is also accepted). A matching value is checked against the actual current resource inside the synchronous write transaction before any write or event. A stale value returns 409 `CONFLICT` with details `{reason:"STALE_REVISION",entityType,entityId,orgId,projectId,currentRevision,fields}` and changes no storage, mentions or events. Malformed preconditions return 422. A missing precondition retains existing partial-update/unconditional-delete behavior. Issue PATCH returns canonical content and therefore requires both issue:read and issue:write before effects; scopes are independent.

Web editors always use this guard. The review panel compares the editing baseline, the current server version and the local draft. It names changed fields, distinguishes conflicting edits and offers Use current / Keep mine. Merge changes without conflicts explicitly adopts nonoverlapping server edits while retaining local work. A new server change after a decision requires another review. Saving sends only changed issue fields. Stale-save errors preserve the draft and fetch current content for review; failed mutations are never automatically resent. Comment removal confirms the identified author and rendered content, then guards that exact version. A changed comment must be reviewed and confirmed again.

Additional read endpoints, under `/api/v1`:

| Method and path | Response and context | Permission |
| --- | --- | --- |
| GET `/comments/:commentId` | `{comment}` with canonical HTML, mention ids and revision; a removed comment returns 404 | issue:read on its actual organization/project |
| GET `/projects/:projectId/issue-context?assigneeId=ID` | `{projectId,orgId,assignee:{user_id,role,name,email}|null}` for the selected current member only | issue:read plus members:read on the actual organization/project |

CLI `issue show` and comment list/add/update expose current revision in JSON. Conditional commands are `crew issue update ISSUE_ID --title TEXT --if-revision REVISION`, `crew issue comment update COMMENT_ID --body TEXT --if-revision REVISION` and `crew issue comment delete COMMENT_ID --if-revision REVISION`. A conflict reports current context and tells the caller to fetch, review and explicitly choose a new revision. Omitting the option preserves existing commands.

The version 1 JSON transfer document remains exact and unchanged: its two exporter presenter calls explicitly exclude revisions. Export/import validation, reference mapping, Markdown text and planning behavior are preserved.

Server integration helper `modules/work/revisions.js` exports `contentRevision(namespace,canonicalValues)`, `issueRevision(issue)`, `commentRevision(comment)` and `assertRevision(req,current,entityType)`. Generic content serialization recursively sorts object keys, preserves array order and rejects unsupported/nonfinite JSON values. Only the issue wrapper treats label ids as a sorted set; workflow/board arrays retain meaningful order. Hashing uses server-only node:crypto. Shared `issue-edit.js` contains the pure three-way review model; shared Markdown occurrence parsing remains the sole mention parser.

## Dependency exploration and cycle repair

Issue detail includes a keyboard-usable Dependency explorer. It starts at the issue you opened and shows named current neighbors with blocks/blocked by, duplicates/duplicated by and symmetric relates to labels. Status badges distinguish Done from Unfinished. Filter by relation kind and incoming/outgoing direction, page explicitly through all neighbors, expand a neighbor to inspect its current links, or focus it. Back returns to the previous focus; Return to the original issue resets exploration. Changing the root issue/project resets history and expansions. Transient errors retain visible data with explicit Reload/Refresh; current access denials clear protected results. A page loads at most the selected API limit; the explorer does not preload the graph or stop at the first 200 dependencies.

GET `/api/v1/issues/:issueId/dependencies` accepts `kind=all|blocks|duplicates|relates`, `direction=all|incoming|outgoing`, `limit` 1–200 and opaque `cursor`. It returns `{focus:Issue,items:Relation[],nextCursor}` using the existing canonical relation/issue presenters. It requires issue:read for the actual focus and each returned neighbor, restricts adjacency to the focus's current project, and includes symmetric relates links in either direction filter. It is read-only and emits no domain event. `crew issue dependencies ISSUE_ID --kind blocks --direction incoming --limit 50 --json` uses the same API; pass `--cursor` with unchanged filters for later pages.

Rejected blocker and duplicate cycles keep their stable 422 `targetId` field error and add `cycle:{kind,path,proposed}` details. `path` is the real existing target-to-source chain, projected to id/key/title/status context; `proposed` identifies the rejected source and target. The web shows those existing links in order and explains that an existing relation must be changed before adding the proposed closing link. Rejection inserts no relation and emits no event. Duplicate single-target and symmetric related-work rules remain unchanged. The one relation writer uses one shared visited traversal: stream indexed outgoing edges, visit each reached id once, retain one predecessor, and reconstruct one deterministic real witness. Historical cyclic input terminates, and branching paths are not exhaustively enumerated.

Canonical relation creation returns the other issue and therefore checks issue:read and issue:write for both source and target before any effect. Label PATCH returns retained canonical fields and checks project issue:read alongside issue:write before reading the current label or changing it. Write-only denied calls leave both storage and event history unchanged.
