export function IssuePicker({ projectId, value, onChange, excludeId, label = 'Parent issue', error }) {
  const [search, setSearch] = useState('');
  const [cursor, setCursor] = useState('');
  const result = useResource(() => api.get('/projects/' + projectId + '/issues', { q: search, limit: 20, cursor }), [projectId, search, cursor]);
