    <Field label={label} error={error} hint="Select a result or paste its issue id. Clear the id to remove the selection.">
      <input value={value} placeholder="No issue selected" onInput={event => onChange(event.currentTarget.value)} />
    </Field>
    <Field label={'Find ' + label.toLowerCase()}>
      <input type="search" value={search} placeholder="Search title or key" onInput={event => { setSearch(event.currentTarget.value); setCursor(''); }} />
    </Field>
    <ErrorNotice error={result.error} />
    {result.loading ? <Loading label="Finding issues…" /> :
      <select value="" aria-label={'Select ' + label.toLowerCase()} onChange={event => onChange(event.currentTarget.value)}>
        <option value="">Select a matching issue…</option>
        {result.data?.items?.filter(issue => issue.id !== excludeId).map(issue => <option key={issue.id} value={issue.id}>{issue.key} · {issue.title}</option>)}
      </select>}
    <div class="actions">
      {result.data?.nextCursor && <button type="button" onClick={() => setCursor(result.data.nextCursor)}>More matches</button>}
      {cursor && <button type="button" onClick={() => setCursor('')}>First matches</button>}
      {value && <button type="button" class="subtle" onClick={() => onChange('')}>Clear selection</button>}
    </div>
  </div>;
}
export function IssueForm({ project, workflow, labels, initial, onSave, onCancel, onConflict, canEdit = true }) {
  const [review, setReview] = useState(() => createDraftReview(issueDraft(initial), initial?.revision));
  const draft = review.draft;
  useEffect(() => { if (initial) setReview(previous => refreshDraftReview(previous, issueDraft(initial), initial.revision)); }, [initial]);
  const [errors, setErrors] = useState({});
  const [error, setError] = useState(null);
  const [saving, setSaving] = useState(false);
  const change = (field, value) => setReview(previous => changeDraftReview(previous, field, value));
  async function submit(event) {
    event.preventDefault();
    const details = validateIssueDraft(draft);
    if (reviewChanges(review).length) { setError(new Error('Review the current server changes before saving.')); return; }
    setErrors(details);
    if (Object.keys(details).length) return;
    setSaving(true); setError(null);
    try {
      const payload = issuePayload(draft);
      const changed = initial ? changedDraftFields(review) : Object.keys(payload);
      if (!changed.length) { setError(new Error('There are no issue changes to save.')); return; }
      await onSave(Object.fromEntries(changed.map(field => [field, payload[field]])), review.revision);
    }
    catch (caught) { setError(caught); setErrors(caught.status === 422 ? caught.details ?? {} : {}); if (caught.status === 409) onConflict?.(); }
    finally { setSaving(false); }
  }
  return <form class="panel" aria-label={initial ? 'Edit issue' : 'Create issue'} onSubmit={submit}>
    <DraftReview review={review} onChange={setReview} />
    {!canEdit && <p role="status">Your draft is preserved. Current access does not allow saving this issue.</p>}
    <Field label="Title" error={errors.title}>
      <input name="title" value={draft.title} maxLength={500} required disabled={saving} onInput={event => change('title', event.currentTarget.value)} />
    </Field>
    <MarkdownComposer label="Description" name="description" value={draft.description} onChange={value => change('description', value)}
      orgId={project.orgId} contextKey={initial?.id ?? 'new-issue'} maxLength={100000} disabled={saving} error={errors.description} />
    <div class="overview-grid">
      <Field label="Status" error={errors.statusId}>
        <select name="statusId" value={draft.statusId} onChange={event => change('statusId', event.currentTarget.value)}>
          {!initial && <option value="">First workflow status</option>}
          {workflow.map(status => <option key={status.id} value={status.id}>{status.name}</option>)}
        </select>
      </Field>
      <Field label="Priority" error={errors.priority}>
        <select name="priority" value={draft.priority} onChange={event => change('priority', event.currentTarget.value)}>
          {priorities.map(priority => <option key={priority.value} value={priority.value}>{priority.label}</option>)}
        </select>
      </Field>
      <div>
        <IssueMemberSelect projectId={project.id} orgId={project.orgId} label="Assignee" name="assigneeId"
          value={draft.assigneeId} onChange={value => change('assigneeId', value)} emptyLabel="Unassigned" disabled={saving}
          hint="Choose a current organization member. Browse additional pages for more names." />
        {errors.assigneeId && <p role="alert" class="error">{errors.assigneeId}</p>}
      </div>
      <Field label="Estimate" error={errors.estimate} hint="A nonnegative number; leave empty for no estimate.">
        <input name="estimate" type="number" min="0" max="1000000" step="any" value={draft.estimate} onInput={event => change('estimate', event.currentTarget.value)} />
      </Field>
      <Field label="Due date" error={errors.dueDate}>
        <input name="dueDate" type="date" value={draft.dueDate} onInput={event => change('dueDate', event.currentTarget.value)} />
      </Field>
    </div>
    <IssuePicker projectId={project.id} value={draft.parentId} excludeId={initial?.id} onChange={value => change('parentId', value)} error={errors.parentId} />
    <fieldset><legend>Labels</legend>
      {!labels.length && <p>No labels exist yet. Create them in project label settings.</p>}
      {labels.map(label => <label key={label.id} class="actions">
        <input type="checkbox" checked={draft.labelIds.includes(label.id)} onChange={() => change('labelIds', toggleLabel(draft.labelIds, label.id))} />
        <span class="badge" style={{ borderLeft: '4px solid ' + label.color }}>{label.name}</span>
      </label>)}
      {errors.labelIds && <p class="error" role="alert">{errors.labelIds}</p>}
    </fieldset>
    <ErrorNotice error={error?.details?.reason === 'STALE_REVISION' ? new Error(error.message) : error} />
    <div class="actions">
      <button type="submit" disabled={saving || project.archived || !canEdit || reviewChanges(review).length > 0}>{saving ? 'Saving…' : initial ? 'Save issue' : 'Create issue'}</button>
      {onCancel && <button type="button" class="subtle" disabled={saving} onClick={onCancel}>Cancel</button>}
    </div>
  </form>;
}
