    </div>
    {canWrite && <form onSubmit={add} aria-label="Add relation">
      <Field label="This issue…">
        <select name="relationKind" value={kind} onChange={event => setKind(event.currentTarget.value)}>
          <option value="blocks">blocks the selected issue</option>
          <option value="duplicates">duplicates the selected canonical issue</option>
          <option value="relates">relates to the selected issue</option>
        </select>
      </Field>
      <IssuePicker label="Related issue" projectId={issue.projectId} excludeId={issue.id} value={targetId} onChange={setTargetId} error={error?.details?.targetId} />
      <p>Blocking and duplicate links are directional. Related links appear the same from either issue. Cycles are rejected.</p>
      <button type="submit" disabled={saving}>{saving ? 'Adding…' : 'Add relation'}</button>
    </form>}
  </section>;
}
