}
export function RelationsPanel({ issue, canWrite }) {
  const [cursor, setCursor] = useState('');
  const resource = useResource(() => api.get('/issues/' + issue.id + '/relations', { limit: 30, cursor }), [issue.id, cursor]);
  const [targetId, setTargetId] = useState('');
  const [kind, setKind] = useState('relates');
  const [error, setError] = useState(null);
  const [saving, setSaving] = useState(false);
  async function add(event) {
    event.preventDefault();
    if (!targetId) { setError(new Error('Choose a related issue first.')); return; }
    setSaving(true); setError(null);
    try { await api.post('/issues/' + issue.id + '/relations', { targetId, kind }); setTargetId(''); resource.refresh(); }
    catch (caught) { setError(caught); }
    finally { setSaving(false); }
  }
  async function remove(id) {
    setSaving(true); setError(null);
    try { await api.delete('/relations/' + id); resource.refresh(); }
    catch (caught) { setError(caught); }
    finally { setSaving(false); }
  }
  return <section class="panel" aria-label="Issue relations">
    <h2>Related work</h2>
    <ErrorNotice error={error?.details?.cycle ? new Error(error.message) : error ?? resource.error} />
    <CycleExplanation cycle={error?.details?.cycle} />
    {resource.loading ? <Loading label="Loading relations…" /> :
      !resource.data?.items?.length ? <EmptyState title="No related issues">Link dependencies, duplicates or supporting work.</EmptyState> :
      <ul>{resource.data.items.map(relation => <li key={relation.id}>
        <span>{relation.label} </span><Link href={'/issues/' + relation.otherIssue.id}>{relation.otherIssue.key} · {relation.otherIssue.title}</Link>
        {canWrite && <button type="button" class="subtle" disabled={saving} onClick={() => void remove(relation.id)}>Remove relation</button>}
      </li>)}</ul>}
    <div class="actions">
      {resource.data?.nextCursor && <button type="button" onClick={() => setCursor(resource.data.nextCursor)}>Next relations</button>}
      {cursor && <button type="button" onClick={() => setCursor('')}>First relations</button>}
    </div>
    {canWrite && <form onSubmit={add} aria-label="Add relation">
      <Field label="This issue…">
        <select name="relationKind" value={kind} onChange={event => setKind(event.currentTarget.value)}>
          <option value="blocks">blocks the selected issue</option>
          <option value="duplicates">duplicates the selected canonical issue</option>
          <option value="relates">relates to the selected issue</option>
        </select>
      </Field>
      <IssuePicker label="Related issue" projectId={issue.projectId} excludeId={issue.id} value={targetId} onChange={setTargetId} error={error?.details?.targetId} />
      <p>Blocking and duplicate links are directional. Related links appear the same from either issue. Cycles are rejected.</p>
      <button type="submit" disabled={saving}>{saving ? 'Adding…' : 'Add relation'}</button>
    </form>}
  </section>;
}
